/* ---------- v25 GFX: 마법사 · 사제 스킬 아이콘 다시 그리기 (사용자 2026-10-10) ----------
   · 예전에는 마법사·사제 아이콘을 '종류(화살·원·장판…) × 원소'로 자동으로 그려, 같은 그림을 쓰는 스킬이 많았다(사제 100개 중 61개, 마법사 132개 중 35개).
     이제 스킬마다 다른 무료 그림(game-icons.net, CC BY 3.0 · 출처는 시작 화면 「소리 · 음악 출처」 아래)을 하나씩 정해 쓴다(IC25.MAP: 스킬 id → 그림 이름, IC25.P: 그림 → 모양).
   · 색: 마법사는 예전처럼 원소 색(불 주황, 물·얼음 하늘, 바람 민트, 번개 파랑, 대지 황토, 비전 보라, 빛 노랑). 사제는 계열 색:
     심판 = 금빛, 퇴마 = 보라빛, 치유 = 초록(예전 그대로), 수호 = 파랑, 축복 = 분홍. 1차는 스킬 나무의 탭이 곧 계열, 2·3차는 하는 일로 정한다(IC25.PFAM).
   · 하급/상급: 1~3위계는 그림만, 4~6위계는 뒤에 은은한 빛, 7위계 이상(상위 기술·2·3차 포함)은 더 밝은 빛과 진한 테두리. 패시브는 예전처럼 점선 고리.
     2차 은청 · 3차 진홍 테두리와 Ⅱ/Ⅲ 문양(tier22.js), 3차 마법사·사제의 금빛 테두리(job3fx-mp.js MPJ_FRAME)는 그대로.
   · 그리기만 바뀐다(SVG 문자열). 규칙 · 수치 · 맞는 판정 · 저장과 무관. 전사 · 궁수(iconsphys.js)는 이미 스킬마다 다른 그림이라 그대로.
   · icons.js의 spellIcon이 IC25.svg(s)를 먼저 부른다(표에 없으면 예전 그림). 같은 아이콘을 여러 번 그려도 되도록 결과를 기억해 둔다. */
const IC25={
  FAM:{judg:['#ffd04a','#3a2806','#fff6d2'],exor:['#c4a4ff','#22123e','#f4ecff'],heal:['#8fe38a','#0f3a14','#ecffe8'],guard:['#7fb8ff','#0c2246','#e8f2ff'],bless:['#ff9cc8','#3e1028','#ffecf5']},
  FAMN:{judg:'심판',exor:'퇴마',heal:'치유',guard:'수호',bless:'축복'},
  PTAB:['judg','exor','heal','guard','bless'],// 사제 1차 나무 탭 0~4
  // 2·3차 사제 기술의 계열 (하는 일로)
  PFAM:{lightvolley:'judg',conviction:'judg',heresybrand:'judg',purgefire:'exor',judgechain:'judg',penitence:'judg',confessbell:'exor',inqarmor:'guard',holyflame:'exor',finalverdict:'judg',heavenblades:'judg',grandverdict:'exor',
    grandblessing:'bless',graceamp:'heal',gracelink:'heal',lifespring:'heal',chainheal:'heal',hymnecho:'bless',purifyhand:'heal',sanctum:'guard',lightwings:'bless',archhymn:'heal',battlerez:'heal',crownofblessing:'bless',
    execlance:'judg',execeye:'judg',heavenwrath:'exor',brandspread:'judg',lightchaser:'judg',condemnfield:'exor',heavenprison:'exor',atonelight:'bless',judgespear:'judg',execution:'judg',heavengate:'exor',
    sainttouch:'heal',stigmata:'heal',martyrprayer:'heal',lightpath:'heal',consecrate:'bless',graceaccel:'bless',lifeswap:'guard',saintmarch:'heal',sanctumfield:'guard',grandrez:'heal',saintmiracle:'heal'},
  fam(s){if(!s||s.cls!=='priest')return null;if(this.PFAM[s.id])return this.PFAM[s.id];const t=typeof TREE!=='undefined'?TREE[s.id]:null;return this.PTAB[+t]||'judg'},
  pal(s){const f=this.fam(s);if(f)return this.FAM[f];const p=PAL[s.el]||PAL.arcane;return (s.kind==='heal'||s.kind==='hot')?['#9fe39a','#103a14',p[2]]:p},
  tier(s){const r=s.rank||1;return r>=7?2:r>=4?1:0},
  has(s){return !!(s&&this.MAP[s.id]&&this.P[this.MAP[s.id]]&&!s.phys&&s.el!=='phys')},
  memo:new Map(),
  svg(s){const k=s.id+'|'+(s.rank||0)+'|'+s.kind;let h=this.memo.get(k);if(h)return h;
    const [c,dk,hi]=this.pal(s),t=this.tier(s),id=s.id.replace(/[^a-z0-9_]/gi,''),pas=s.kind==='passive';
    const d=this.P[this.MAP[s.id]];/* v25 메인: svg 겹쳐 쓰기(use) 대신 같은 모양을 두 번 적는다 — 게임 링크 올리기에서 href가 든 페이지를 막는 검사에 걸려서 */
    const j3=typeof isJ3mp==='function'&&isJ3mp(s.id)&&typeof MPJ_FRAME!=='undefined';
    const sc=pas?.0391:.0488,o=pas?6:3.5;// 패시브는 고리 안에 작게
    h=`<svg viewBox="0 0 32 32" aria-hidden="true"><defs><radialGradient id="ig${id}" cx=".4" cy=".35" r=".8"><stop offset="0" stop-color="${dk}"/><stop offset="1" stop-color="#050404"/></radialGradient>`+
      `<linearGradient id="il${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${hi}"/><stop offset=".6" stop-color="${c}"/><stop offset="1" stop-color="${c}" stop-opacity=".8"/></linearGradient>`+
      `</defs>`+
      `<rect x=".5" y=".5" width="31" height="31" rx="3" fill="url(#ig${id})" stroke="${c}" stroke-opacity="${[.35,.55,.85][t]}"${t===2?' stroke-width="1.2"':''}/>`+
      (t?`<circle cx="16" cy="16" r="${t===2?13:11}" fill="${c}" opacity="${t===2?.22:.13}"/>`:'')+
      `<g transform="translate(${o} ${o}) scale(${sc})"><path d="${d}" fill="#000" opacity=".65" transform="translate(12 16)"/><path d="${d}" fill="url(#il${id})"/></g>`+
      (pas?`<circle cx="16" cy="16" r="14" stroke="${c}" stroke-width="1" stroke-dasharray="2.5 2.5" fill="none" opacity=".8"/>`:'')+
      (t===2&&!pas?`<path d="M2 7V2h5M25 2h5v5M30 25v5h-5M7 30H2v-5" stroke="${hi}" stroke-width="1" fill="none" opacity=".75"/>`:'')+
      (j3?MPJ_FRAME:'')+`</svg>`;
    this.memo.set(k,h);return h},
  CREDIT:'마법사 · 사제 스킬 아이콘: game-icons.net — Lorc, Delapouite, sbed, Willdabeast, Skoll, Caro Asercion, HeavenlyDog (CC BY 3.0, 색을 입힘)'};
