setTimeout(()=>{try{const el=document.getElementById('auCredits');if(el&&!el.querySelector('.ic25cr')){const p=document.createElement('p');p.className='muted ic25cr';p.style.cssText='font-size:12px;margin:4px 0 0';p.textContent=IC25.CREDIT;el.appendChild(p)}}catch(_){}},0);
